query:
fragment dashboardTeam on Team {
  id
  name
  standing
  totalTeamMatchesPlayed
  isTied
  division {
    id
    type
    isTournament
    __typename
  }
  league {
    id
    slug
    __typename
  }
  session {
    id
    name
    __typename
  }
  tournaments(time: FUTURE) {
    id
    tournamentTypeName
    __typename
  }
  __typename
}

query dashboardTeams {
  viewer {
    id
    ... on Member {
      leagueTeams: teams(type: [RELEASED, WEEKLY], current: true) {
        ...dashboardTeam
        __typename
      }
      tournamentTeams: teams(type: [TOURNAMENT], current: true) {
        ...dashboardTeam
        __typename
      }
      __typename
    }
    __typename
  }
}
